const fs = require('fs');
const input = { ...$input.first().json };

const inputPath = '/tmp/odoo_04_claude_input.json';
fs.writeFileSync(inputPath, JSON.stringify(input), 'utf8');

return [{
  json: {
    ok: true,
    input_path: inputPath,
    snapshot_id: input.snapshot_id,
    message: 'Input JSON written for Claude audit prepare',
  },
}];

const item = $input.first().json;

if (item.exitCode !== undefined && Number(item.exitCode) !== 0) {
  throw new Error(
    `Claude prepare failed (exit ${item.exitCode}). stderr: ${item.stderr || ''}`,
  );
}

const stdout = String(item.stdout || '').trim();
if (!stdout) {
  throw new Error(
    `Claude prepare returned empty stdout. stderr: ${item.stderr || ''}`,
  );
}

const lastLine = stdout.split(/\r?\n/).filter(Boolean).pop();

try {
  return [{ json: JSON.parse(lastLine) }];
} catch (e) {
  throw new Error(
    `Could not parse Claude prepare stdout as JSON: ${e.message}. stdout starts: ${stdout.slice(0, 500)}`,
  );
}

const fs = require('fs');

const prep = $input.first().json;
const inputPath = '/tmp/odoo_04_claude_call_input.json';

fs.writeFileSync(inputPath, JSON.stringify(prep), 'utf8');

return [{
  json: {
    ok: true,
    input_path: inputPath,
    snapshot_id: prep.snapshot_id,
    claude_model: prep.claude_model,
  },
}];

const item = $input.first().json;

if (item.exitCode !== undefined && Number(item.exitCode) !== 0) {
  throw new Error(
    `Claude API call failed (exit ${item.exitCode}). stderr: ${item.stderr || ''}`,
  );
}

const stdout = String(item.stdout || '').trim();
if (!stdout) {
  throw new Error(
    `Claude API call returned empty stdout. stderr: ${item.stderr || ''}`,
  );
}

const lastLine = stdout.split(/\r?\n/).filter(Boolean).pop();

try {
  return [{ json: JSON.parse(lastLine) }];
} catch (e) {
  throw new Error(
    `Could not parse Claude API stdout as JSON: ${e.message}. stdout starts: ${stdout.slice(0, 500)}`,
  );
}
